-- Additiv innehållskatalog för Yei Habibi. Historiska order-/betalningstabeller lämnas orörda.
-- Endast Next.js-servern får läsa råa utkast. Publika webben och Expo använder en filtrerad API-vy.
create table public.hospitality_content (
  id smallint primary key default 1 check (id = 1),
  catalog jsonb not null,
  revision integer not null default 1 check (revision > 0),
  updated_at timestamptz not null default now(),
  constraint hospitality_content_shape check (
    jsonb_typeof(catalog) = 'object'
    and catalog ?& array['menus','dishes','venues','contact','preview']
    and jsonb_typeof(catalog->'menus') = 'array'
    and jsonb_array_length(catalog->'menus') = 4
    and jsonb_typeof(catalog->'dishes') = 'array'
    and jsonb_array_length(catalog->'dishes') <= 100
    and jsonb_typeof(catalog->'venues') = 'array'
    and jsonb_array_length(catalog->'venues') = 4
    and jsonb_typeof(catalog->'contact') = 'object'
    and jsonb_typeof(catalog->'preview') = 'boolean'
  )
);
alter table public.hospitality_content enable row level security;
revoke all on public.hospitality_content from public, anon, authenticated;
grant select, insert, update on public.hospitality_content to service_role;

